using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Threading;

// Detached lowering audit. These methods are not generated by dotobj yet.
internal static unsafe class BarrierProbe
{
    private static nint clearMemory = (nint)(delegate* managed<void*, int, nuint, void*>)&ClearMemory;
    private static void* ClearMemory(void* address, int value, nuint size)
    {
        NativeMemory.Fill(address, size, (byte)value);
        return address;
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    internal static int Reload(int* address)
    {
        int before = *address;
        Thread.MemoryBarrier();
        return before + *address;
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    internal static int CoalescedRead(int* address) => *address + *address;

    [MethodImpl(MethodImplOptions.NoInlining)]
    internal static void Scrub(byte* address, nuint size)
    {
        NativeMemory.Clear(address, size);
        Thread.MemoryBarrier();
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    internal static void ScrubIndirect(byte* address, nuint size)
    {
        ((delegate* managed<void*, int, nuint, void*>)Volatile.Read(ref clearMemory))(address, 0, size);
        Thread.MemoryBarrier();
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    internal static void BarrierOnly(byte* address, nuint size)
    {
        // The owned emitter must evaluate memory operands before this call.
        // Their assembly constraint does not authorize a fabricated CLR load
        // or store through the operand pointer.
        Thread.MemoryBarrier();
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    internal static void OperandEffects(byte* address, ref int offset, ref int extents)
    {
        byte* evaluatedAddress = address + offset++;
        nuint evaluatedExtent = (nuint)(++extents);
        BarrierOnly(evaluatedAddress, evaluatedExtent);
    }

    static void Check(bool condition, string name)
    {
        if (!condition) throw new Exception(name);
        Console.WriteLine(name);
    }

    public static int Main()
    {
        byte* data = (byte*)NativeMemory.Alloc(4098);
        if (data == null) throw new OutOfMemoryException();
        try
        {
            new Span<byte>(data, 4098).Fill(0xa5);
            int scalar = 37;
            Check(Reload(&scalar) == 74 && CoalescedRead(&scalar) == 74, "reload result");
            BarrierOnly(data, 4098);
            Check(new ReadOnlySpan<byte>(data, 4098).IndexOfAnyExcept((byte)0xa5) == -1, "barrier does not write operands");
            // This tests the proposed helper's own pointer-neutral contract,
            // not the validity of a C asm lvalue at an invalid source address.
            BarrierOnly((byte*)1, nuint.MaxValue);
            Check(true, "barrier does not read operands");
            int offset = 1, extents = 0;
            OperandEffects(data, ref offset, ref extents);
            Check(offset == 2 && extents == 1, "address and extent effects once");
            Scrub(data + 1, 4096);
            Check(new ReadOnlySpan<byte>(data + 1, 4096).IndexOfAnyExcept((byte)0) == -1 &&
                  data[0] == 0xa5 && data[4097] == 0xa5, "unaligned zeroization and sentinels");
            new Span<byte>(data + 1, 4096).Fill(0xa5);
            ScrubIndirect(data + 1, 4096);
            Check(new ReadOnlySpan<byte>(data + 1, 4096).IndexOfAnyExcept((byte)0) == -1 &&
                  data[0] == 0xa5 && data[4097] == 0xa5, "volatile callback zeroization and sentinels");
            Scrub(data, 0);
            Check(data[0] == 0xa5, "zero extent does not write");
        }
        finally { NativeMemory.Free(data); }
        return 0;
    }
}
